import csv, os, re
from collections import defaultdict


def _num(s):
    s = str(s or '').strip().replace('\xa0', '').replace(' ', '')
    if not s:
        raise ValueError('empty')
    if ',' in s and '.' in s:
        if s.rfind(',') > s.rfind('.'):
            s = s.replace('.', '').replace(',', '.')
        else:
            s = s.replace(',', '')
    elif ',' in s:
        s = s.replace(',', '.')
    return float(s)


def _mon(v, name):
    if v is None or v == '':
        return None
    v = str(v).strip()
    if not re.fullmatch(r'\d{4}-(0[1-9]|1[0-2])', v):
        raise ValueError(f'{name} must be YYYY-MM')
    return v


def _find(folder):
    base = os.path.join('.', 'inbox', folder)
    if not os.path.isdir(base):
        raise ValueError(f'folder not found: {folder}')
    for root, _, files in os.walk(base):
        for f in files:
            if f.lower() == 'sales_2026.csv':
                return os.path.join(root, f)
    raise ValueError('sales_2026.csv not found in folder')


def _read(path):
    txt = open(path, encoding='utf-8-sig', newline='').read()
    first = txt.split('\n', 1)[0]
    d = ';' if first.count(';') > first.count(',') else ','
    import io
    return list(csv.DictReader(io.StringIO(txt), delimiter=d))


def _bw(items, key):
    if not items:
        return None, None
    b = max(items, key=lambda x: x[key])
    w = min(items, key=lambda x: x[key])
    return b, w


def run(inp):
    if not isinstance(inp, dict) or not isinstance(inp.get('folder'), str) or not inp['folder']:
        raise ValueError('folder (string) is required')
    fm = _mon(inp.get('from_month'), 'from_month')
    tm = _mon(inp.get('to_month'), 'to_month')
    cf = (inp.get('category_filter') or '').strip().lower()
    cu = (inp.get('customer_filter') or '').strip().lower()
    rows = _read(_find(inp['folder']))
    agg = defaultdict(lambda: [0.0, 0.0, 0])
    skipped = []
    used = 0
    for i, r in enumerate(rows, 2):
        try:
            m = r['month'].strip()
            c = r['category'].strip()
            u = _num(r['units'])
            rev = _num(r['revenue_czk'])
            cust = (r.get('customer') or '').strip()
        except Exception as e:
            skipped.append({'line': i, 'reason': str(e)})
            continue
        if fm and m < fm or tm and m > tm:
            continue
        if cf and c.lower() != cf:
            continue
        if cu and cu not in cust.lower():
            continue
        a = agg[(m, c)]
        a[0] += u
        a[1] += rev
        a[2] += 1
        used += 1
    mbc = [{'month': m, 'category': c, 'units': round(a[0], 2), 'revenue_czk': round(a[1], 2), 'row_count': a[2]}
           for (m, c), a in sorted(agg.items())]
    mt = defaultdict(float)
    ct = defaultdict(float)
    for x in mbc:
        mt[x['month']] += x['revenue_czk']
        ct[x['category']] += x['revenue_czk']
    monthly = [{'month': k, 'revenue_czk': round(v, 2)} for k, v in sorted(mt.items())]
    cats = [{'category': k, 'revenue_czk': round(v, 2)} for k, v in sorted(ct.items())]
    b, w = _bw(monthly, 'revenue_czk')
    per = []
    for c in sorted(ct):
        items = [x for x in mbc if x['category'] == c]
        cb, cw = _bw(items, 'revenue_czk')
        per.append({'category': c,
                    'best_month': {'month': cb['month'], 'revenue_czk': cb['revenue_czk']},
                    'worst_month': {'month': cw['month'], 'revenue_czk': cw['revenue_czk']}})
    return {'monthly_by_category': mbc, 'monthly_totals': monthly, 'category_totals': cats,
            'best_month': b or {}, 'worst_month': w or {}, 'best_worst_by_category': per,
            'source_rows_total': len(rows), 'source_rows_used': used, 'skipped_rows': skipped}

